 if(name==="music")panel.innerHTML=`<div class="adminSectionHead"><div><p class="sectionEyebrow">Music Control</p><h2>Music Manager</h2></div></div><p class="adminLead">Drop a preview to read available audio metadata, fill the release information, and optionally publish it immediately. Filenames such as <code>Artist - Track Title.mp3</code> are understood automatically.</p><form class="appForm adminEditor musicSmartEditor" id="musicForm"><section class="musicSmartHeader"><div><span class="musicSmartIcon">♫</span><div><strong id="musicEditorTitle">Smart Release Publisher</strong><small>Reads ID3 title, artist, genre, BPM, key and release date when available.</small></div></div><label class="musicInstantToggle"><input type="checkbox" name="instantPublish" checked><span><strong>Instant publish</strong><small>Publish automatically when preview audio is dropped</small></span></label></section><div class="musicMetadataStatus" id="musicMetadataStatus"><strong>Waiting for audio</strong><span>Drop a preview or full release to prepare the fields automatically.</span></div><div class="formRow"><label>Track title<input name="title" required placeholder="Loaded from selected filename"></label><label>Artist<input name="artist" value="Seeker Of SoundZ" placeholder="Artist or collaborators"></label></div><div class="formRow"><label>Genre<select name="genrePreset" id="musicGenrePreset">${MUSIC_GENRES.map(g=>`<option value="${g}">${g}</option>`).join("")}<option value="__custom__">＋ Create a genre</option></select></label><label id="musicCustomGenreLabel" hidden>Custom genre<input name="genreCustom" placeholder="Enter your new genre"></label></div><div class="formRow"><label>Release type<select name="releaseType"><option>Single</option><option>EP</option><option>Album</option><option>DJ Edit</option><option>Remix</option><option>Live Set</option><option>Mix</option><option>Sample Pack</option><option>Preset Pack</option><option>Other</option></select></label><label>Tags<input name="tags" placeholder="dubstep, bass music, dark, festival"></label></div><div class="formRow"><label>Price<input name="price" type="number" min="0" step="0.01" value="2.99"></label><label>Release date<input name="releaseDate" type="date"></label></div><div class="formRow"><label>BPM<input name="bpm" type="number" min="0" placeholder="Auto-detected when tagged"></label><label>Key<input name="musicalKey" placeholder="F Minor"></label></div><label>Description<textarea name="description" maxlength="700" placeholder="Describe the sound, story, credits, or release details..."></textarea></label><div class="formRow"><label>Preview audio path<input name="preview" id="musicPreviewPath" placeholder="assets/audio/night-drive-preview.mp3"></label><label>Full/download audio path<input name="full" placeholder="assets/audio/night-drive-full.mp3"></label></div><div class="musicCommerceConfig"><div class="formRow"><label>External purchase URL<input name="purchaseUrl" type="url" placeholder="https://your-store.com/track"></label><label>Purchase button text<input name="purchaseCta" placeholder="Buy Full Release"></label></div><div class="formRow"><label>Preview label<input name="previewLabel" placeholder="60-second preview"></label><label>License / usage<input name="license" placeholder="Personal use license"></label></div></div><div class="formRow"><label>Artwork path<input name="artwork" id="musicArtworkPath" placeholder="assets/images/night-drive.jpg"></label><label>Formats<input name="formats" placeholder="MP3, WAV, STEMS"></label></div><div class="adminDropGrid adminDropGridThree musicDropGrid"><div class="adminDropZone" id="musicArtworkDrop" tabindex="0"><strong>Drop cover artwork</strong><span>Automatically attaches to the current release</span><input type="file" id="musicArtworkFile" accept="image/*" hidden><div class="adminDropPreview" id="musicArtworkPreview"></div></div><div class="adminDropZone musicPrimaryDrop" id="musicAudioDrop" tabindex="0"><strong>Drop preview audio</strong><span>Reads metadata and instantly publishes when enabled</span><input type="file" id="musicAudioFile" accept="audio/*" hidden><div class="adminDropPreview" id="musicAudioPreview"></div></div><div class="adminDropZone" id="musicFullDrop" tabindex="0"><strong>Drop full release</strong><span>Updates the instant-published release automatically</span><input type="file" id="musicFullFile" accept="audio/*" hidden><div class="adminDropPreview" id="musicFullPreview"></div></div></div><div class="formRow"><label>Access<select name="access"><option value="purchase">Purchase</option><option value="member">All signed-in members</option><option value="paid">Paid members only</option><option value="public">Free public download</option></select></label><label class="checkLabel"><input name="featured" type="checkbox"> Featured release</label></div><div class="musicPublishActions"><button class="primaryButton" id="musicSubmitButton">Publish Music</button><button class="secondaryButton" id="cancelMusicEdit" type="button" hidden>Cancel Edit</button><small>Instant publishing can be disabled above when you want to review every field first.</small></div></form><div class="adminList musicAdminList">${music.length?music.slice().reverse().map(t=>`<article class="adminListItem musicAdminItem" data-edit-music="${t.id}" tabindex="0" role="button" aria-label="Edit ${esc(t.title)}"><div class="adminItemPreview">${t.artwork?`<img src="${esc(t.artwork)}" alt="">`:'<span>♪</span>'}</div><div class="musicAdminItemCopy"><strong>${esc(t.title)}</strong><p>${esc(t.artist||'Seeker Of SoundZ')} • ${esc(t.releaseType||'Single')} • ${esc(t.genre||'Music')} • ${esc(t.access)} • $${Number(t.price||0).toFixed(2)}${t.tags?.length?`<br><small>${esc(t.tags.join(" • "))}</small>`:""}</p><small>${esc(musicMediaLabel(t.preview,"Preview"))}</small>${t.full?`<small>${esc(musicMediaLabel(t.full,"Full release"))}</small>`:''}${t.purchaseUrl?`<div class="musicAdminPreviewMeta"><span>Purchase linked</span>${t.previewLabel?`<span>${esc(t.previewLabel)}</span>`:''}${t.license?`<span>${esc(t.license)}</span>`:''}</div>`:''}</div><div class="adminItemActions"><button class="smallAction" data-edit-music="${t.id}" type="button">Edit</button><button class="smallAction dangerAction" data-delete-music="${t.id}" type="button">Delete</button></div></article>`).join(""):'<div class="emptyState">No custom music yet.</div>'}</div>`;
 if(name==="videos")panel.innerHTML=`<div class="adminSectionHead"><div><p class="sectionEyebrow">Video Studio</p><h2 id="videoEditorTitle">Video Manager</h2></div></div><p class="adminLead">Create video posts with a thumbnail, description, and YouTube, Vimeo, Twitch, or local MP4 link. Clicking the thumbnail on the Videos page opens the embedded player.</p><form class="appForm adminEditor" id="videoForm"><div class="formRow"><label>Video title<input name="title" required maxlength="120" placeholder="Live Frequency Session"></label><label>Category<select name="category"><option>Performances</option><option>Studio</option><option>Behind the Scenes</option><option>Shorts</option><option>Tutorials</option><option>Music Videos</option><option>Livestreams</option><option>Creative</option></select></label></div><label>Description<textarea name="description" required maxlength="1000" placeholder="Describe the video..."></textarea></label><label>Video link<input name="link" type="url" required placeholder="https://youtube.com/watch?v=..."></label><label>Thumbnail path<input name="thumbnail" id="videoThumbnailPath" placeholder="assets/images/video-thumbnail.jpg or use drop zone"></label><div class="adminDropZone" id="videoThumbnailDrop" tabindex="0"><strong>Drop video thumbnail here</strong><span>or click to choose an image</span><input type="file" id="videoThumbnailFile" accept="image/*" hidden><div class="adminDropPreview" id="videoThumbnailPreview"></div></div><label class="checkLine"><input type="checkbox" name="featured"> Feature this video at the top of the library</label><div class="adminFormActions"><button class="primaryButton" id="videoSubmitButton">Publish Video</button><button class="secondaryButton" type="button" id="cancelVideoEdit" hidden>Cancel Edit</button></div></form><div class="adminList">${videos.length?videos.slice().reverse().map(v=>`<article class="adminListItem"><div class="adminItemPreview">${v.thumbnail?`<img src="${esc(v.thumbnail)}" alt="">`:'<span>▶</span>'}</div><div><strong>${esc(v.title)}</strong><p>${esc(v.category||'Video')} • ${v.featured?'Featured':'Published'}</p><small>${esc(v.link)}</small></div><div class="adminItemActions"><button class="smallAction" data-edit-video="${v.id}">Edit</button><button class="smallAction dangerAction" data-delete-video="${v.id}">Delete</button></div></article>`).join(''):'<div class="emptyState">No custom videos yet.</div>'}</div>`;
 if(name==="gallery")panel.innerHTML=`<div class="adminSectionHead"><div><p class="sectionEyebrow">Visual Archive</p><h2 id="galleryEditorTitle">Gallery Manager</h2></div></div><p class="adminLead">Upload and organize gallery photos without editing HTML. Images are automatically resized and compressed for the local site.</p><form class="appForm adminEditor" id="galleryForm"><div class="formRow"><label>Image title<input name="title" required maxlength="80" placeholder="Live Frequency"></label><label>Category<select name="category"><option value="headshots">Headshots</option><option value="events">Events</option><option value="production">Production</option><option value="behind-scenes">Behind the Scenes</option><option value="other">Other</option></select></label></div><label>Description<textarea name="description" maxlength="700" placeholder="Tell visitors about this moment..."></textarea></label><div class="formRow"><label>Photographer / credit<input name="credit" maxlength="100" placeholder="Optional"></label><label>Image layout<select name="layout"><option value="standard">Standard</option><option value="tall">Tall</option><option value="wide">Wide</option></select></label></div><label>Image path (optional)<input name="image" placeholder="assets/images/gallery-photo.jpg"></label><div class="adminDropZone galleryDropZone" id="galleryImageDrop" tabindex="0"><strong>Drop gallery image here</strong><span>JPG, PNG, or WebP — automatically optimized</span><input type="file" id="galleryImageFile" accept="image/*" hidden><div class="adminDropPreview" id="galleryImagePreview"></div></div><div class="adminEditorActions"><button class="primaryButton" id="gallerySubmitButton">Publish Image</button><button class="secondaryButton" type="button" id="cancelGalleryEdit" hidden>Cancel Edit</button></div></form><div class="adminList">${gallery.length?gallery.slice().reverse().map(g=>`<article class="adminListItem"><div class="adminItemPreview">${g.image?`<img src="${esc(g.image)}" alt="">`:'<span>▧</span>'}</div><div><strong>${esc(g.title)}</strong><p>${esc(g.category)}${g.credit?` • ${esc(g.credit)}`:''}</p><small>${esc(g.description||'No description')}</small></div><div class="adminItemActions"><button class="smallAction" data-edit-gallery="${g.id}">Edit</button><button class="smallAction dangerAction" data-delete-gallery="${g.id}">Delete</button></div></article>`).join(''):'<div class="emptyState">No gallery images yet. Drop your first image above.</div>'}</div>`;
