panel.classList.add("adminPanelReady");
let activePanel="overview",panelSwitchTimer=0;
function switchAdminPanel(name){
 if(!name||name===activePanel||panel.classList.contains("adminPanelSwitching"))return;
 const savedY=window.scrollY;
 const oldHeight=panel.offsetHeight;
 panel.style.minHeight=`${oldHeight}px`;
 panel.classList.add("adminPanelSwitching","adminPanelFadeOut");
 clearTimeout(panelSwitchTimer);
 panelSwitchTimer=setTimeout(()=>{
  render(name);
  activePanel=name;
  window.scrollTo({top:savedY,left:0,behavior:"instant"});
  panel.classList.remove("adminPanelFadeOut");
  panel.classList.add("adminPanelFadeIn");
  requestAnimationFrame(()=>requestAnimationFrame(()=>panel.classList.remove("adminPanelFadeIn")));
  setTimeout(()=>{panel.style.minHeight="";panel.classList.remove("adminPanelSwitching")},320);
 },130);
}
